while (group_count > 1) {
    assert(i < BITMAP_MAX_LEVELS);
    binfo->levels[i].group_offset = binfo->levels[i-1].group_offset + group_count;
    group_count = BITMAP_BITS2GROUPS(group_count);
    i++;
}
binfo->levels[i].group_offset = binfo->levels[i-1].group_offset + group_count;
assert(binfo->levels[i].group_offset <= BITMAP_GROUPS_MAX);
binfo->nlevels = i;
binfo->nbits = nbits;

